{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    for name in ('nodes', 'core_distance', 'distances'):
        if name not in case:
            raise ValueError('missing required field: ' + name)

    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    if not isinstance(nodes, list) or not isinstance(core, dict) or not isinstance(distances, list):
        raise ValueError('invalid required field type')
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError('nodes must be distinct strings')
    if set(core) != set(nodes):
        raise ValueError('core_distance keys must exactly match nodes')

    def valid_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if not valid_number(core[node]) or core[node] < 0:
            raise ValueError('invalid core distance')

    node_set = set(nodes)
    seen_pairs = set()
    edges = []
    for position, entry in enumerate(distances):
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError('each distance entry must be a triple')
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError('distance endpoints must be strings')
        if left not in node_set or right not in node_set or left == right:
            raise ValueError('invalid distance endpoint')
        if not valid_number(distance) or distance < 0:
            raise ValueError('invalid distance value')
        first, second = (left, right) if left < right else (right, left)
        pair = (first, second)
        if pair in seen_pairs:
            raise ValueError('duplicate undirected distance edge')
        seen_pairs.add(pair)
        weight = max(core[first], core[second], distance)
        edges.append((weight, first, second, position))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    selected = []
    for weight, left, right, position in sorted(edges, key=lambda edge: (edge[0], edge[1], edge[2], edge[3])):
        if union(left, right):
            selected.append([left, right, weight])
            if len(selected) == len(nodes) - 1:
                break

    if nodes and len(selected) != len(nodes) - 1:
        raise ValueError('distance graph is disconnected')
    return {'mst_edges': selected, 'total_weight': sum(edge[2] for edge in selected)}
